-- =============================================================================
-- 532 — LE CAHIER D'EXERCICES DE 1RE (partie 20)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 532 --niveau 1re --fichiers francais.n6b,francais.n7a,francais.n7b,francais.n8a,francais.n8b --suffixe 20 > supabase/contenu/532_exercices_1re_20.sql
--
-- 90 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   francais.n6b            18 exercices · 6 chapitres
--   francais.n7a            18 exercices · 6 chapitres
--   francais.n7b            18 exercices · 6 chapitres
--   francais.n8a            18 exercices · 6 chapitres
--   francais.n8b            18 exercices · 6 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('356220af-27cc-5951-b438-50d5817f26c3'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Deux camps devant Troie","competence":"analyser-document","situation":"Tu fiches la grande épopée grecque pour ton cours. Repère son identité, puis les deux camps qui s’affrontent devant Troie.","documents":[{"id":"fiche","type":"fiche","modele":"affiche","entete":"Iliade","sousTitre":"Homère","emoji":"🏛️","lignes":[{"id":"z1","texte":"Composition","valeur":"Vers le VIIIe siècle av. J.-C."},{"id":"z2","texte":"Forme","valeur":"Vingt-quatre chants en hexamètres"},{"id":"z3","texte":"Durée racontée","valeur":"Cinquante et un jours de la dixième année"},{"id":"z4","texte":"Sujet annoncé","valeur":"La colère d’Achille"}],"pied":"Épopée fondatrice","teinte":"ambre"},{"id":"camps","type":"tableau","titre":"Les deux camps","colonnes":["Camp","Ses héros"],"lignes":[["Les Achéens (Grecs)","Achille, Agamemnon, Patrocle, Ulysse, Nestor, Ajax"],["Les Troyens","?"]],"enteteLignes":true}],"questions":[{"enonce":"Que faut-il écrire dans la case « ? » pour les Troyens ?","aide":"Hector est le champion de Troie, et Priam son roi.","type":"choix","options":[{"id":"a","texte":"Achille, Hector, Ajax, Nestor, Priam"},{"id":"b","texte":"Patrocle, Briséis, Priam, Nestor, Hélène"},{"id":"c","texte":"Agamemnon, Hélène, Ulysse, Pâris, Ajax"},{"id":"d","texte":"Hector, Priam, Andromaque, Pâris, Hélène"}],"multiple":false},{"enonce":"Touche la ligne qui dit en combien de chants le poème est composé.","aide":"Cherche un nombre écrit en toutes lettres.","type":"zone","document":"fiche","multiple":false},{"enonce":"Complète avec la fiche et le cours.","aide":"Le premier mot annonce le sujet du poème.","type":"trous","segments":["Le poème raconte la ",0," d’Achille ; la guerre de Troie est née de l’enlèvement d’Hélène par le Troyen ",1,"."],"banque":["Ulysse","colère","joie","Pâris","Hector"]},{"enonce":"Touche la case qui nomme les héros de l’armée grecque.","aide":"Les Achéens sont les Grecs.","type":"zone","document":"camps","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"Les Troyens ont pour héros **Hector, Priam, Andromaque, Pâris et Hélène**."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Le poème compte **vingt-quatre chants**, en hexamètres."},{"cle":{"type":"trous","trous":[["colere"],["paris"]]},"affichage":"colère · Pâris","explication":"Le sujet annoncé est **la colère** d’Achille ; Hélène a été enlevée par **Pâris**."},{"cle":{"type":"zone","ids":["r0c1"]},"explication":"Les héros grecs sont **Achille, Agamemnon, Patrocle, Ulysse, Nestor et Ajax**."}]$ex$::jsonb),
  ('356220af-27cc-5951-b438-50d5817f26c3'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"De la colère aux funérailles","competence":"analyser-texte","situation":"Le poème ne raconte pas toute la guerre de Troie, mais quelques jours. Suis la colère d’Achille jusqu’à la scène qui clôt le poème.","documents":[{"id":"colere","type":"chaine","titre":"La colère d’Achille","disposition":"colonne","noeuds":[{"id":"z1","texte":"Agamemnon prend Briséis à Achille"},{"id":"z2","texte":"Achille se retire du combat"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Achille revient et tue Hector"},{"id":"z5","texte":"Priam supplie Achille de rendre le corps"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]},{"id":"chant","type":"texte","genre":"recit","titre":"Le dernier chant","blocs":["Priam entre sous la tente d’Achille. Il se jette à ses pieds et le supplie de lui rendre le corps de son fils Hector.","Alors les deux ennemis pleurent ensemble, l’un son fils, l’autre son ami."],"source":"Résumé écrit pour l’exercice, d’après le cours"}],"questions":[{"enonce":"Quelle étape manque dans la chaîne (la case « ? ») ?","aide":"Qu’est-ce qui fait sortir Achille de sa colère ?","type":"choix","options":[{"id":"a","texte":"Hector emporte Briséis à Troie et se réfugie dans les murs"},{"id":"b","texte":"Patrocle revêt les armes d’Achille et meurt, tué par Hector"},{"id":"c","texte":"Les Grecs rentrent chez eux et abandonnent le siège"},{"id":"d","texte":"Agamemnon s’excuse et rend Briséis à Achille"}],"multiple":false},{"enonce":"Touche le verbe qui dit ce que Priam demande à Achille.","aide":"Priam est un vieux roi qui s’humilie.","type":"zone","document":"chant","multiple":false},{"enonce":"Touche le verbe qui montre que la pitié réunit les ennemis.","aide":"Achille et Priam partagent la même émotion.","type":"zone","document":"chant","multiple":false},{"enonce":"Relie chaque personnage à son rôle dans l’action.","aide":"Suis les noms dans l’ordre de la chaîne.","type":"association","gauche":[{"id":"g0","texte":"Agamemnon"},{"id":"g1","texte":"Patrocle"},{"id":"g2","texte":"Hector"},{"id":"g3","texte":"Priam"}],"droite":[{"id":"d0","texte":"Il vient supplier Achille de lui rendre le corps de son fils"},{"id":"d1","texte":"Il prend Briséis à Achille"},{"id":"d2","texte":"Il tue Patrocle, puis meurt de la main d’Achille"},{"id":"d3","texte":"Il revêt les armes d’Achille et meurt"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"L’étape manquante est **la mort de Patrocle**, tué par Hector : elle ramène Achille au combat."},{"cle":{"type":"zone","ids":["m15"]},"explication":"Priam **supplie** Achille de lui rendre le corps de son fils : la grandeur passe par la pitié."},{"cle":{"type":"zone","ids":["m29"]},"explication":"Les deux ennemis **pleurent** ensemble : le poème montre le coût de la guerre pour tous."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g2":"d2","g1":"d3"}},"explication":"**Agamemnon** offense, **Patrocle** meurt en armure d’Achille, **Hector** tue puis est tué, **Priam** supplie."}]$ex$::jsonb),
  ('356220af-27cc-5951-b438-50d5817f26c3'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une épopée qui ne chante pas la guerre","competence":"argumenter","situation":"Le poème célèbre-t-il la guerre ? Lis une scène écrite à la manière de l’épopée, puis un débat, et construis la réponse.","documents":[{"id":"scene","type":"texte","genre":"recit","titre":"Les adieux, à la manière de l’épopée","blocs":["Hector, au casque ombragé d’un panache de crin, tend les bras vers son fils. L’enfant, effrayé, se rejette contre le sein de sa nourrice : il a peur du casque de bronze.","Le père enlève le casque, et la mère, qui pleurait, sourit à travers ses larmes."],"source":"Texte écrit pour l’exercice, à la manière de l’*Iliade*"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Zoé","emoji":"👧","cote":"gauche"},{"nom":"Idris","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Zoé","texte":"L’*Iliade* glorifie la guerre : on n’y parle que de combats et de héros."},{"qui":"Idris","texte":"Regarde la scène d’Hector et d’Andromaque : le poème montre ce que la guerre coûte aux familles."},{"qui":"Zoé","texte":"Mais il prend parti pour les Grecs ?"},{"qui":"Idris","texte":"Non : sa compassion est égale pour les deux camps, jusqu’aux funérailles d’Hector."}]}],"questions":[{"enonce":"Touche l’objet qui effraie l’enfant.","aide":"C’est une pièce de l’armure du père.","type":"zone","document":"scene","multiple":false},{"enonce":"Touche le mot qui dit comment le poème traite les deux camps.","aide":"Il ne prend pas parti.","type":"zone","document":"deb","multiple":false},{"enonce":"Quelle lecture le texte et le dialogue appuient-ils ?","aide":"Relis la dernière réplique d’Idris.","type":"choix","options":[{"id":"a","texte":"Le poème glorifie la guerre sans rien montrer de ses victimes"},{"id":"b","texte":"Le poème montre le coût de la guerre, avec compassion pour les deux camps"},{"id":"c","texte":"Le poème n’est qu’un catalogue de généalogies et de bateaux"},{"id":"d","texte":"Le poème prend parti pour les Troyens contre les Grecs"}],"multiple":false},{"enonce":"Relie chaque procédé de l’épopée à son exemple.","aide":"Chaque procédé donne à l’épopée son ampleur.","type":"association","gauche":[{"id":"g0","texte":"Épithète de nature"},{"id":"g1","texte":"Comparaison développée"},{"id":"g2","texte":"Catalogue"},{"id":"g3","texte":"Intervention des dieux"}],"droite":[{"id":"d0","texte":"Le guerrier comparé à un lion, un incendie, une vague"},{"id":"d1","texte":"Athéna et Héra pour les Grecs, Apollon et Aphrodite pour Troie"},{"id":"d2","texte":"Le dénombrement des vaisseaux"},{"id":"d3","texte":"Achille « aux pieds légers »"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m30"]},"explication":"L’enfant a peur du **casque** de son père : la guerre entre jusque dans la tendresse familiale."},{"cle":{"type":"zone","ids":["m44"]},"explication":"La compassion est **égale** pour les Grecs et les Troyens : le poème n’en choisit aucun."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le poème **ne célèbre pas la guerre** : il en montre **le coût**, avec une compassion égale pour les deux camps."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g2":"d2","g0":"d3"}},"explication":"L’**épithète** est une formule fixe, la **comparaison** s’étend, le **catalogue** énumère, les **dieux** prennent parti."}]$ex$::jsonb),
  ('0e084d60-56de-55d2-936a-c369b3ab5dca'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Un recueil publié sans son auteur","competence":"se-reperer-temps","situation":"Tu prépares une fiche sur le recueil de Rimbaud. Place-le dans le temps, puis relève ses caractéristiques.","documents":[{"id":"frise","type":"frise","titre":"Rimbaud et ses textes","debut":1850,"fin":1895,"pas":5,"evenements":[{"id":"z1","date":1854,"nom":"Naissance"},{"id":"z2","date":1873,"nom":"Une saison en enfer"},{"id":"z3","date":1886,"nom":"Illuminations"},{"id":"z4","date":1891,"nom":"Mort"}]},{"id":"fiche","type":"fiche","modele":"affiche","entete":"Illuminations","sousTitre":"Arthur Rimbaud","emoji":"🌅","lignes":[{"id":"z5","texte":"Forme","valeur":"Poèmes en prose et quelques vers libres"},{"id":"z6","texte":"Écrites","valeur":"Vers 1873-1875"},{"id":"z7","texte":"Publiées par","valeur":"Verlaine, en 1886"}],"pied":"Recueil de visions","teinte":"violet"}],"questions":[{"enonce":"Touche la ligne qui dit qui fait paraître le recueil.","aide":"Rimbaud est alors parti pour l’Afrique et le commerce.","type":"zone","document":"fiche","multiple":false},{"enonce":"Combien d’années séparent la parution d’*Une saison en enfer* de celle des *Illuminations* ?","aide":"Lis les deux dates sur la frise et soustrais.","type":"nombre","unite":"ans"},{"enonce":"Touche l’année de la mort de Rimbaud.","aide":"Il meurt à Marseille, bien après avoir cessé d’écrire.","type":"zone","document":"frise","multiple":false},{"enonce":"Complète avec la fiche.","aide":"Rimbaud n’a pas choisi l’éditeur.","type":"trous","segments":["Les *Illuminations* sont surtout des poèmes en ",0," ; elles sont publiées par ",1,"."],"banque":["Hugo","prose","Baudelaire","Verlaine","vers"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z7"]},"explication":"**Verlaine** fait paraître le recueil en 1886 : Rimbaud n’y a pris aucune part."},{"cle":{"type":"nombre","valeur":13,"tolerance":0},"affichage":"13 ans","explication":"1886 − 1873 = **13 ans** : *Une saison en enfer* est le seul livre que Rimbaud ait fait imprimer lui-même."},{"cle":{"type":"zone","ids":["z4"]},"explication":"Rimbaud meurt en **1891**, à Marseille."},{"cle":{"type":"trous","trous":[["prose"],["verlaine"]]},"affichage":"prose · Verlaine","explication":"Ce sont des poèmes en **prose**, publiés par **Verlaine** en 1886."}]$ex$::jsonb),
  ('0e084d60-56de-55d2-936a-c369b3ab5dca'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Aube : la poursuite d’une déesse","competence":"analyser-texte","situation":"Les *Illuminations* n’ont ni récit ni sujet stable, mais « Aube » est une petite aventure. Lis le résumé, puis repère les thèmes du recueil.","documents":[{"id":"aube","type":"texte","genre":"recit","titre":"Le fil d’« Aube »","blocs":["Dans « Aube », le poète poursuit la déesse-aube à travers la campagne. Il la rejoint au bout de sa course et l’embrasse : « J’ai embrassé l’aube d’été. »","Le poème s’achève sur son réveil."],"source":"Résumé écrit pour l’exercice ; vers cité : Arthur Rimbaud, « Aube »"},{"id":"themes","type":"tableau","titre":"Quelques thèmes du recueil","colonnes":["Titre","Thème"],"lignes":[["Villes","La ville moderne et fantastique"],["Enfance","?"],["Départ","La rupture : « Assez vu. »"]],"enteteLignes":true}],"questions":[{"enonce":"Que faut-il écrire dans la case « ? » pour « Enfance » ?","aide":"Le titre le dit déjà.","type":"choix","options":[{"id":"a","texte":"Le deuil et le remords"},{"id":"b","texte":"L’enfance et l’émerveillement"},{"id":"c","texte":"La guerre et la politique"},{"id":"d","texte":"Le commerce et le voyage"}],"multiple":false},{"enonce":"Touche le mot qui désigne ce que le poète poursuit.","aide":"L’aube prend la forme d’un être divin.","type":"zone","document":"aube","multiple":false},{"enonce":"Touche le mot qui marque la fin du poème.","aide":"C’est le moment où le poète sort du rêve.","type":"zone","document":"aube","multiple":false},{"enonce":"Remets dans l’ordre les trois moments d’« Aube ».","aide":"La poursuite précède l’étreinte, le réveil clôt le poème.","type":"ordre","items":[{"id":"a","texte":"Le poète s’élance à la poursuite de l’aube"},{"id":"b","texte":"Il s’éveille"},{"id":"c","texte":"Il l’embrasse au bout de sa course"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"« Enfance » développe le thème de **l’enfance et de l’émerveillement**, comme « Aube »."},{"cle":{"type":"zone","ids":["m6"]},"explication":"Le poète poursuit **la déesse**-aube : l’aube est personnifiée."},{"cle":{"type":"zone","ids":["m35"]},"explication":"Le poème s’achève sur **le réveil** du poète."},{"cle":{"type":"ordre","ids":["a","c","b"]},"explication":"Ordre : **poursuite**, **étreinte** (« J’ai embrassé l’aube d’été »), **réveil**."}]$ex$::jsonb),
  ('0e084d60-56de-55d2-936a-c369b3ab5dca'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Voir ce qui n’existe pas","competence":"argumenter","situation":"Que fait un poème comme ceux des *Illuminations* : décrire le réel ou inventer ? Lis le programme du voyant, écoute un débat, puis conclus.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Le programme du voyant","blocs":["Je dis qu’il faut être voyant, se faire voyant.","Le Poète se fait voyant par un long, immense et raisonné dérèglement de tous les sens."],"source":"Arthur Rimbaud, lettre à Paul Demeny, 15 mai 1871"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Paul","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Les *Illuminations* décrivent des villes que Rimbaud a vues."},{"qui":"Paul","texte":"Non : ses villes sont suspendues, avec des ponts de cristal. Le poème ne décrit plus, il produit une réalité."},{"qui":"Inès","texte":"Alors le lecteur doit chercher l’histoire cachée ?"},{"qui":"Paul","texte":"Il n’y en a pas : ce sont des visions juxtaposées, avec des changements brusques."}]}],"questions":[{"enonce":"Touche le mot qui dit comment le poète se fait voyant.","aide":"Le poète bouleverse ses sens.","type":"zone","document":"lettre","multiple":false},{"enonce":"Touche le verbe qui dit ce que fait le poème, d’après Paul.","aide":"Il ne décrit plus.","type":"zone","document":"deb","multiple":false},{"enonce":"Range chaque trait : ce que font les *Illuminations*, ou ce qu’elles ne font pas.","aide":"Le débat dit qu’il n’y a ni histoire cachée ni description.","type":"categories","categories":[{"id":"c0","texte":"Ce qu’elles font"},{"id":"c1","texte":"Ce qu’elles ne font pas"}],"items":[{"id":"i0","texte":"Raconter une histoire suivie"},{"id":"i1","texte":"Juxtaposer des visions"},{"id":"i2","texte":"Produire une réalité"},{"id":"i3","texte":"Décrire un voyage réel"}]},{"enonce":"Quelle réponse les *Illuminations* donnent-elles à la question : la poésie doit-elle rendre compte du réel ou inventer ?","aide":"Pense aux villes suspendues et aux ponts de cristal.","type":"choix","options":[{"id":"a","texte":"Elles répondent : décrire fidèlement ce que l’on voit"},{"id":"b","texte":"Elles répondent : imiter les règles de la tragédie"},{"id":"c","texte":"Elles répondent : raconter une histoire vraie en vers"},{"id":"d","texte":"Elles répondent : inventer un monde, des visions"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m21"]},"explication":"Le poète se fait voyant par **le dérèglement** de tous les sens : c’est le programme que réalisent les *Illuminations*."},{"cle":{"type":"zone","ids":["m25"]},"explication":"Le poème **produit** une réalité : il invente un monde plutôt que de rendre compte du réel."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1"}},"explication":"Les *Illuminations* **juxtaposent des visions** et **produisent une réalité** ; elles ne racontent **pas d’histoire suivie** ni de **voyage réel**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les *Illuminations* répondent **inventer** : le poète voyant produit un monde au lieu de décrire le réel."}]$ex$::jsonb),
