   $ex${"titre":"Les Romarins : une source, un secret, un bossu","competence":"se-reperer-temps","situation":"Le domaine des Romarins a un secret. Suis les étapes du drame, de la source bouchée à la source rouverte.","documents":[{"id":"fil","type":"chaine","titre":"Le drame des Romarins","disposition":"colonne","noeuds":[{"id":"z1","texte":"Le Papet et Ugolin bouchent la source en secret"},{"id":"z2","texte":"Jean s’installe aux Romarins"},{"id":"z3","texte":"Il porte des seaux et s’endette"},{"id":"z4","texte":"?"},{"id":"z5","texte":"Les Soubeyran rachètent et débouchent la source"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]}],"questions":[{"enonce":"Quelle étape manque dans la chaîne (la case « ? ») ?","aide":"Les Soubeyran ne rachètent le domaine qu’après la mort de Jean.","type":"choix","options":[{"id":"a","texte":"Jean vend les Romarins au Papet et reprend son métier ailleurs"},{"id":"b","texte":"Jean abandonne le domaine et repart vers la ville avec sa fille"},{"id":"c","texte":"Jean découvre la source bouchée et accuse le Papet devant le village"},{"id":"d","texte":"Jean meurt, tué par une charge de mine en creusant pour trouver l’eau"}],"multiple":false},{"enonce":"Touche l’étape qui explique pourquoi Jean manque d’eau.","aide":"Qui prive le domaine de sa source, et dans quel but ?","type":"zone","document":"fil","multiple":false},{"enonce":"Relie chaque personnage ou groupe à son rôle dans le drame.","aide":"Pense à ce que chacun fait ou sait du secret.","type":"association","gauche":[{"id":"g0","texte":"Le Papet et Ugolin"},{"id":"g1","texte":"Jean de Florette"},{"id":"g2","texte":"Manon"},{"id":"g3","texte":"Le village"}],"droite":[{"id":"d0","texte":"Elle voit, cachée, déboucher la source"},{"id":"d1","texte":"Il s’épuise à chercher l’eau et en meurt"},{"id":"d2","texte":"Il sait et se tait"},{"id":"d3","texte":"Ils bouchent la source, puis la débouchent"}]}]}$ex$::jsonb,
