  ('4d8539df-30e5-5e96-b0fe-ebe65e6adc31'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Un silence au bord du chemin","competence":"argumenter","situation":"Jean est-il l’artisan de son malheur ? Lis le débat de deux élèves, puis une courte scène écrite à la manière du roman : le texte tranche.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Théo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Jean est le seul responsable : il aurait dû abandonner les Romarins avant de s’épuiser."},{"qui":"Théo","texte":"Il ne sait pas que la source est bouchée ; le village, lui, le sait et se tait."},{"qui":"Inès","texte":"Le village ne fait rien de mal : il ne dit rien, c’est tout."},{"qui":"Théo","texte":"Justement : c’est ce silence qui rend le drame possible."}]},{"id":"sc","type":"texte","genre":"recit","titre":"Sur le chemin des Romarins","blocs":["Au village, tout le monde sait où court l’eau de la colline. Sur le chemin des Romarins, un paysan croise le bossu qui monte, ses deux seaux pleins à la main.","— Bonne santé, monsieur ! lui dit-il en souriant.","Puis il continue sans rien dire de la source bouchée. À la fontaine, personne ne lui en parlera non plus."],"source":"Texte écrit pour l’exercice, à la manière de Marcel Pagnol"}],"questions":[{"enonce":"Touche le mot qui désigne le secret que Jean ignore.","aide":"Théo parle de ce qu’on a fait à la source.","type":"zone","document":"deb","multiple":false},{"enonce":"Touche les deux mots qui montrent un villageois aimable en apparence mais complice par son silence.","aide":"Cherche un mot de gentillesse et un mot qui dit ce qu’il ne fait pas.","type":"zone","document":"sc","multiple":true},{"enonce":"Quelle lecture la scène soutient-elle le mieux ?","aide":"Que sait le paysan, et que fait-il de ce qu’il sait ?","type":"choix","options":[{"id":"a","texte":"Le Papet agit par vengeance contre le caractère de Jean"},{"id":"b","texte":"Jean se perd seul, par entêtement et par orgueil de citadin"},{"id":"c","texte":"Le malheur de Jean est organisé par le silence complice des autres"},{"id":"d","texte":"Les villageois ignorent tout de la source qu’on a bouchée"}],"multiple":false},{"enonce":"Relie chaque effet de construction à son sens.","aide":"Pense à ce que ressent le lecteur, puis à ce que fait le village.","type":"association","gauche":[{"id":"g0","texte":"Le lecteur sait la source bouchée, pas Jean"},{"id":"g1","texte":"Les villageois restent aimables et muets"},{"id":"g2","texte":"Deux hommes qui se taisent suffisent"},{"id":"g3","texte":"Un bossu qui se fie aux livres"}],"droite":[{"id":"d0","texte":"Le crime est un secret partagé"},{"id":"d1","texte":"Le mal n’a rien de spectaculaire"},{"id":"d2","texte":"L’étranger sans défense face au pays"},{"id":"d3","texte":"Une tension tragique : on voit venir le piège"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m23"]},"explication":"Jean ignore que la source est **bouchée** : tout le drame vient de ce secret."},{"cle":{"type":"zone","ids":["m38","m44"]},"explication":"Il parle en **souriant** mais ne veut rien **dire** : l’amabilité cache un silence complice."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le paysan **sait** et **se tait** : le drame naît du silence complice, pas du seul caractère de Jean."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g3":"d2","g0":"d3"}},"explication":"Le roman est **tragique** parce que le lecteur sait ; le **silence** rend le crime collectif ; le mal est banal ; Jean, étranger, ne connaît que ses livres."}]$ex$::jsonb),
