   $ex${"titre":"Parler sans rien dire","competence":"analyser-texte","situation":"Lis un court échange écrit à la manière de Lagarce, puis relève comment la parole se reprend, se corrige et passe à côté de l’essentiel.","documents":[{"id":"sc","type":"texte","genre":"theatre","titre":"Un dimanche, à table","blocs":[{"didascalie":"Un dimanche, à table. Antoine parle à Louis, qui vient d’arriver."},{"personnage":"Antoine","replique":"Tu restes pour le déjeuner, enfin pour la journée. Non, ce n’est pas ça : pour le dimanche."},{"personnage":"Louis","replique":"Je suis venu pour… non, rien. Je suis juste fatigué, voilà."},{"personnage":"La Mère","replique":"Tu as faim ? On ne parle pas de ça aujourd’hui."}],"source":"Texte écrit pour l’exercice, à la manière de Jean-Luc Lagarce"}],"questions":[{"enonce":"Touche les deux mots qu’Antoine remplace l’un par l’autre en se reprenant.","aide":"Il dit d’abord un mot, puis le corrige.","type":"zone","document":"sc","multiple":true},{"enonce":"Touche l’adverbe par lequel Louis minimise ce qui lui arrive.","aide":"Un petit mot qui réduit l’importance, comme dans le titre de la pièce.","type":"zone","document":"sc","multiple":false},{"enonce":"Relie chaque procédé de la pièce à son effet.","aide":"Pense à ce que ressent le public, puis à ce que la famille ne sait pas.","type":"association","gauche":[{"id":"g0","texte":"Phrases reprises, corrigées, réajustées"},{"id":"g1","texte":"La maladie jamais nommée"},{"id":"g2","texte":"Un prologue qui annonce la fin"},{"id":"g3","texte":"Le retour d’un fils que personne ne fête"}],"droite":[{"id":"d0","texte":"La parole cherche ce qu’elle n’arrive pas à dire"},{"id":"d1","texte":"Un détournement de la parabole du fils prodigue"},{"id":"d2","texte":"Le public sait ce que la famille ignore"},{"id":"d3","texte":"L’essentiel reste hors des mots"}]},{"enonce":"Pourquoi la maladie de Louis n’est-elle jamais nommée ?","aide":"Relis la réplique de la Mère : de quoi ne parle-t-on pas aujourd’hui ?",