  ('f05f8ecb-de8f-574a-b258-486900fabba2'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Écrire à partir d’une photographie jamais prise","competence":"analyser-texte","situation":"Lis un court texte écrit à la manière de Duras, puis explique ce que ses choix d’écriture produisent.","documents":[{"id":"sc","type":"texte","genre":"recit","titre":"Sur le bac","blocs":["Je suis sur le bac. Le fleuve est large. Le fleuve est lent.","Elle porte un chapeau d’homme. Elle ne sait pas encore qu’on la regarde.","Personne n’a pris la photographie. C’est de cette absence que viennent les phrases."],"source":"Texte écrit pour l’exercice, à la manière de Marguerite Duras"}],"questions":[{"enonce":"Touche les deux mots par lesquels la narratrice parle de la jeune fille à distance, comme d’une autre.","aide":"Le « je » du début laisse place à une troisième personne.","type":"zone","document":"sc","multiple":true},{"enonce":"Touche le mot que le texte répète d’une phrase à l’autre.","aide":"Deux phrases courtes commencent par les mêmes mots.","type":"zone","document":"sc","multiple":true},{"enonce":"Relie chaque trait d’écriture de *L’Amant* à son effet.","aide":"Pense à ce que chaque procédé fait entendre ou voir.","type":"association","gauche":[{"id":"g0","texte":"Pas de chronologie"},{"id":"g1","texte":"Alternance du « je » et du « elle »"},{"id":"g2","texte":"Phrases courtes, répétitions, blancs"},{"id":"g3","texte":"Une photographie jamais prise"}],"droite":[{"id":"d0","texte":"Un récit éclaté, fait de mémoire"},{"id":"d1","texte":"Un rythme obsédant"},{"id":"d2","texte":"L’absence qui autorise la littérature"},{"id":"d3","texte":"La distance entre la narratrice et son personnage varie"}]},{"enonce":"Que suggère l’absence de photographie dans ce texte ?","aide":"Relis la dernière phrase du texte.","type":"choix","options":[{"id":"a","texte":"Que la narratrice invente toute son enfance de A à Z"},{"id":"b","texte":"Que la narratrice refuse absolument de parler de sa jeunesse"},{"id":"c","texte":"Que l’écriture reconstruit une scène qu’aucune image n