  ('4b238bc1-e169-5470-94e8-28d890d14fed'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Qui parle, et que faut-il croire ?","competence":"argumenter","situation":"Deux élèves se disputent : la Folie se moque des docteurs, donc Érasme serait-il contre la religion ? Lis un pastiche, puis tranche.","documents":[{"id":"txt","type":"texte","genre":"recit","titre":"Un discours à la manière de la Folie","blocs":["Écoutez-moi, mortels : je suis la Folie, et je me loue moi-même, car nul autre ne le ferait de si bon cœur. Ôtez-moi, et plus de mariage, plus d’amitié, plus de société : qui supporterait son prochain sans une bonne dose d’illusion ?","Voyez ces docteurs qui parlent si gravement du ciel : ils croient m’avoir chassée, et ils sont mes plus fidèles amis."],"source":"Texte écrit pour l’exercice, à la manière de L’Éloge de la folie d’Érasme"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Léa","emoji":"👧","cote":"gauche"},{"nom":"Sam","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léa","texte":"La Folie critique les docteurs et les moines : Érasme est donc contre la religion."},{"qui":"Sam","texte":"Pas du tout : il critique l’Église de l’intérieur et réclame un retour aux Évangiles."},{"qui":"Léa","texte":"Mais alors pourquoi faire parler la Folie ?"},{"qui":"Sam","texte":"Parce qu’elle peut dire des vérités que personne d’autre ne pourrait dire."}]}],"questions":[{"enonce":"Touche le verbe qui montre que la Folie fait elle-même son éloge.","aide":"Elle parle d’elle-même, à la première personne.","type":"zone","document":"txt","multiple":false},{"enonce":"Qui lit juste, d’après le débat et le cours ?","aide":"Érasme veut réformer sans quitter l’Église.","type":"choix","options":[{"id":"a","texte":"Sam : la Folie dit ce que pense l’Église officielle"},{"id":"b","texte":"Sam : la satire vise des abus, sans rompre avec l’Église"},{"id":"c","texte":"Léa : la satire prouve qu’Érasme rejette toute religion"},{"id":"d","texte":"Léa : Érasme rejoint Luther dans sa rupture avec Rome"}],"multiple":false},{"enonce":"Touche le mot qui nomme les gens visés par la satire dans le second paragraphe.","aide":"Ils parlent « gravement du ciel ».","type":"zone","document":"txt","multiple":false},{"enonce":"Range chaque geste : Érasme le fait-il, ou ne le fait-il pas ?","aide":"Pense à la langue du livre, et à sa relation à Luther.","type":"categories","categories":[{"id":"c0","texte":"Ce qu’Érasme fait"},{"id":"c1","texte":"Ce qu’il ne fait pas"}],"items":[{"id":"i0","texte":"Rompt avec Rome comme Luther"},{"id":"i1","texte":"Réclame le retour aux Évangiles"},{"id":"i2","texte":"Fait parler la Folie elle-même"},{"id":"i3","texte":"Écrit son éloge en français"},{"id":"i4","texte":"Critique l’Église de l’intérieur"}]},{"enonce":"Relie chaque procédé à son effet.","aide":"Le procédé crée un effet de lecture ou de sens.","type":"association","gauche":[{"id":"g0","texte":"Un discours prononcé par la Folie"},{"id":"g1","texte":"Un éloge ironique"},{"id":"g2","texte":"Le retournement final"}],"droite":[{"id":"d0","texte":"Le lecteur doit se demander qui parle et que croire"},{"id":"d1","texte":"La folie de la foi devient sagesse devant Dieu"},{"id":"d2","texte":"Elle dit des vérités que nul ne pourrait dire"}]}]}$ex$::jsonb,
