   $ex${"titre":"Les notes du notaire","competence":"analyser-texte","situation":"Utterson note ce qu’il apprend. Lis ses notes (écrites pour l’exercice), repère les indices, puis remets l’enquête en ordre.","documents":[{"id":"txt","type":"texte","genre":"recit","titre":"Les notes d’Utterson","blocs":["Notes d’Utterson, notaire à Londres. Le testament du docteur Jekyll lègue tout à un inconnu, un certain Hyde.","Un témoin m’a décrit un petit homme repoussant qui a piétiné une fillette sans un regard. Plus tard, un député a été assassiné dans la rue.","Après la mort de Jekyll, deux documents ont été découverts : ils expliquent tout."],"source":"Texte écrit pour l’exercice, à la manière de Stevenson"}],"questions":[{"enonce":"Touche les deux mots qui désignent les violences attribuées à Hyde.","aide":"Une fillette, puis un député.","type":"zone","document":"txt","multiple":true},{"enonce":"Touche le mot qui nomme ce qui livre enfin l’explication.","aide":"Ils sont découverts après la mort de Jekyll.","type":"zone","document":"txt","multiple":false},{"enonce":"Remets ces étapes de l’histoire dans l’ordre.","aide":"Le testament est le premier indice ; la fin est la mort de Jekyll.","type":"ordre","items":[{"id":"a","texte":"Un testament intrigue Utterson"},{"id":"b","texte":"Jekyll se suicide"},{"id":"c","texte":"Hyde tue le député Carew"},{"id":"d","texte":"Jekyll, à court d’ingrédient, s’enferme"}]},{"enonce":"Que cherche Jekyll avec sa potion ?","aide":"Les deux documents expliquent son projet.","type":"choix","options":[{"id":"a","texte":"Séparer chimiquement le bien et le mal en lui"},{"id":"b","texte":"Guérir une maladie incurable de sa famille"},{"id":"c","texte":"Vivre bien plus longtemps que ses contemporains"},{"id":"d","texte":"Devenir invisible aux yeux de toute la ville"}],"multiple":false}]}$ex$::jsonb,
