   $ex${"titre":"Respectable le jour, un autre la nuit","competence":"argumenter","situation":"Pour la dissertation sur l’hypocrisie victorienne, lis un pastiche d’un portrait de notable, puis complète ton argument.","documents":[{"id":"txt","type":"texte","genre":"recit","titre":"Un notable de Londres","blocs":["Le docteur Aldous Wren, que toute la ville respecte, donne chaque dimanche un dîner où l’on parle de charité. Mais chaque nuit, une petite porte sans enseigne, au fond de son jardin, s’ouvre pour un autre homme, que personne ne présente et que tous évitent."],"source":"Texte écrit pour l’exercice, à la manière de Stevenson"},{"id":"arg","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Le récit dénonce l’hypocrisie victorienne","La respectabilité de façade exige une part cachée","?"],["Le récit relève du fantastique à narrateurs multiples","Le lecteur reconstitue la vérité à partir de témoignages","Utterson, Lanyon, puis les deux documents"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux mots qui montrent la façade honorable du docteur Wren.","aide":"Ce que la ville pense de lui, et ce dont on parle à son dîner.","type":"zone","document":"txt","multiple":true},{"enonce":"Quel exemple du récit faut-il écrire dans la case « ? » du tableau ?","aide":"Quel personnage a une façade respectable et une part cachée ?","type":"choix","options":[{"id":"a","texte":"Poole, majordome fidèle, alerte les voisins"},{"id":"b","texte":"Enfield, qui raconte l’épisode de la porte"},{"id":"c","texte":"Jekyll, respectable et généreux, cache Hyde"},{"id":"d","texte":"Carew, victime d’un meurtre en pleine rue"}],"multiple":false},{"enonce":"Touche l’objet qui cache la part secrète du docteur Wren.","aide":"Elle s’ouvre la nuit, au fond du jardin.","type":"zone","document":"txt","multiple":false},{"enonce":"Relie chaque trait du récit à son effet.","aide":"Pense à la place du lecteur face à ce qu’il lit.","type":