   $ex${"titre":"Dire seulement ce qu’on ressent","competence":"argumenter","situation":"Deux élèves discutent : Meursault est-il insensible ? Lis un pastiche à la manière de Camus, puis tranche.","documents":[{"id":"txt","type":"texte","genre":"recit","titre":"Un court passage","blocs":["Le patron m’a demandé si j’avais du chagrin. J’ai répondu que j’étais fatigué. C’était vrai. Il a eu l’air déçu. Il a regardé ses mains, puis il est sorti. J’ai mangé mon pain."],"source":"Texte écrit pour l’exercice, à la manière de L’Étranger de Camus"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Malik","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Il ne répond pas à la question : il est insensible."},{"qui":"Malik","texte":"Il répond, au contraire : il dit seulement ce qu’il ressent, rien de plus."},{"qui":"Inès","texte":"Mais le patron est déçu !"},{"qui":"Malik","texte":"Oui, parce que le narrateur refuse de jouer la comédie des sentiments."}]}],"questions":[{"enonce":"Touche le mot par lequel le narrateur souligne qu’il ne ment pas.","aide":"Il commente sa propre réponse en un seul mot.","type":"zone","document":"txt","multiple":false},{"enonce":"Quelle lecture le texte et le débat confirment-ils ?","aide":"Relis la réponse du narrateur et la réaction du patron.","type":"choix","options":[{"id":"a","texte":"Il ne ressent rien et ne s’en soucie absolument pas"},{"id":"b","texte":"Il cherche volontairement à choquer son patron"},{"id":"c","texte":"Il cache sa tristesse pour ne pas paraître faible"},{"id":"d","texte":"Il refuse de mentir sur ce qu’il ressent, même si cela déçoit"}],"multiple":false},{"enonce":"Range chaque trait : fait-il partie de l’écriture blanche, ou pas ?","aide":"Pense à un ton plat, sans effet ni émotion soulignée.","type":"categories","categories":[{"id":"c0","texte":"Écriture blanche"},{"id":"c1","texte":"Pas écriture blanche"}],"items":[{"id":"i0","texte":"Images appuyées et lyriques"},{"id":"i1","texte":"Phrases courtes et neutres"},{"id":"i2","texte":"Commentaires émus du narrateur"},{"id":"i3","texte":"Première personne, passé composé"}]},{"enonce":"Pourquoi Meursault est-il condamné, selon le cours ?","aide":"Le procès juge un homme plus qu’un acte.","type":"choix","options":[{"id":"a","texte":"Parce qu’il a menti à la justice sur ses sentiments"},{"id":"b","texte":"Parce qu’il refuse de jouer la comédie des sentiments"},{"id":"c","texte":"Parce qu’aucun témoin ne vient parler en sa faveur"},{"id":"d","texte":"Parce qu’il a avoué un meurtre prémédité à l’avance"}],"multiple":false}]}$ex$::jsonb,
