   $ex${"titre":"Le fil des notions","competence":"analyser-document","situation":"L’Être et le Néant est un essai : on le suit par le fil des notions. Retrouve la notion manquante, puis relie les exemples célèbres.","documents":[{"id":"fil","type":"chaine","titre":"Le fil des notions","disposition":"colonne","noeuds":[{"id":"z1","texte":"L’existence précède l’essence"},{"id":"z2","texte":"La liberté est totale, donc la responsabilité"},{"id":"z3","texte":"?"},{"id":"z4","texte":"La mauvaise foi : se mentir pour fuir sa liberté"},{"id":"z5","texte":"Le regard d’autrui me fige en objet"}],"liens":[{"de":"z1","a":"z2","texte":"donc"},{"de":"z2","a":"z3","texte":"fait naître"},{"de":"z3","a":"z4","texte":"tentation"},{"de":"z4","a":"z5","texte":"et face à autrui"}]}],"questions":[{"enonce":"Quelle notion manque dans la chaîne (la case « ? ») ?","aide":"Si ma liberté est totale, qu’est-ce qui justifie mes choix ?","type":"choix","options":[{"id":"a","texte":"La nausée : le monde n’a aucun sens"},{"id":"b","texte":"L’angoisse : rien ne fonde mes choix"},{"id":"c","texte":"L’engagement : je choisis un parti politique"},{"id":"d","texte":"La honte : on me surprend par un trou de serrure"}],"multiple":false},{"enonce":"Touche la notion qui décrit une fuite devant la liberté.","aide":"Elle consiste à se mentir à soi-même.","type":"zone","document":"fil","multiple":false},{"enonce":"Relie chaque exemple à ce qu’il montre.","aide":"Trois exemples du livre, une pièce de théâtre.","type":"association","gauche":[{"id":"g0","texte":"Le garçon de café"},{"id":"g1","texte":"La femme au rendez-vous"},{"id":"g2","texte":"Le voyeur surpris par le trou de la serrure"},{"id":"g3","texte":"Huis clos"}],"droite":[{"id":"d0","texte":"La mauvaise foi : elle refuse de choisir"},{"id":"d1","texte":"La honte : je deviens objet sous le regard d’autrui"},{"id":"d2","texte":"La mauvaise foi : il joue son rôle pour se croire une chose"},{"id":"d3","texte":"L’illustration théâtrale du regard d’autrui"}]},{"enonce":"Complète la formule célèbre.","aide":"La liberté est vue comme une charge.","type":"trous","segments":["Selon Sartre, nous sommes ",0," à être ",1,"."],"banque":["esclaves","condamnés","heureux","sauvés","libres"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["b"]},"explication":"Quand je découvre que **rien ne fonde mes choix**, c’est l’**angoisse**."},{"cle":{"type":"zone","ids":["z4"]},"explication":"La **mauvaise foi** est un mensonge à soi-même pour **fuir sa liberté**."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2","g3":"d3"}},"explication":"**Café** et **rendez-vous** = mauvaise foi ; **voyeur** = honte ; **Huis clos** = regard d’autrui."},{"cle":{"type":"trous","trous":[["condamnes"],["libres"]]},"affichage":"condamnés · libres","explication":"Nous sommes **condamnés** à être **libres** : la liberté est totale, et la responsabilité aussi."}]$ex$::jsonb),
  ('47081694-a530-5f50-b8be-f5b8ff6f09ff'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"La déléguée qui joue à être déléguée","competence":"argumenter","situation":"Pour ton oral sur la mauvaise foi, lis une scène inventée, puis départage deux élèves.","documents":[{"id":"txt","type":"texte","genre":"recit","titre":"Au conseil de classe","blocs":["Au conseil de classe, la déléguée joue à être déléguée. Elle hoche la tête un peu trop souvent, sa voix est un peu trop sérieuse, ses notes sont un peu trop bien rangées. Elle s’applique à n’être rien d’autre que ce que l’on attend d’elle."],"source":"Texte écrit pour l’exercice, pour illustrer une notion de Sartre (aucune citation)"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Jade","emoji":"👧","cote":"gauche"},{"nom":"Samir","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Samir","texte":"Elle est simplement sérieuse : il n’y a rien de plus à voir."},{"qui":"Jade","texte":"Non : elle se comporte comme si elle était une chose, la déléguée, au lieu de choisir qui elle est."},{"qui":"Samir","texte":"Mais elle n’a rien d’un menteur !"},{"qui":"Jade","texte":"Elle se ment à elle-même : c’est cela, la mauvaise foi."}]}],"questions":[{"enonce":"Touche le verbe qui dit qu’elle interprète un rôle.","aide":"On le dit d’un comédien.","type":"zone","document":"txt","multiple":false},{"enonce":"Quelle lecture éclaire le mieux la notion de mauvaise foi ?","aide":"Sartre refuse une nature fixée d’avance.","type":"choix","options":[{"id":"a","texte":"Samir : elle est libre parce qu’elle joue bien son rôle"},{"id":"b","texte":"Jade : elle se réduit à un rôle pour fuir sa liberté"},{"id":"c","texte":"Jade : elle est honteuse, comme un voyeur surpris"},{"id":"d","texte":"Samir : son rôle exprime sa nature profonde, fixée d’avance"}],"multiple":false},{"enonce":"Range chaque exemple : mauvaise foi, ou regard d’autrui ?","aide":"L’un concerne mon rapport à moi-même, l’autre mon rapport aux autres.","type":"categories","categories":[{"id":"c0","texte":"Mauvaise foi"},{"id":"c1","texte":"Regard d’autrui"}],"items":[{"id":"i0","texte":"Le voyeur surpris devant un trou de serrure"},{"id":"i1","texte":"Le garçon de café qui joue à être garçon de café"},{"id":"i2","texte":"La femme qui feint de ne pas sentir sa main"},{"id":"i3","texte":"La honte de se savoir regardé"},{"id":"i4","texte":"Se mentir à soi-même pour fuir sa liberté"}]},{"enonce":"« Sommes-nous ce que nous faisons ? » Pourquoi Sartre répond-il oui ?","aide":"L’existence précède l’essence.","type":"choix","options":[{"id":"a","texte":"Parce que la nature humaine, donnée à la naissance, fixe nos actes d’avance"},{"id":"b","texte":"Parce que la société décide seule de ce que nous devenons"},{"id":"c","texte":"Parce que seules les choses se définissent par ce qu’elles font"},{"id":"d","texte":"Parce que l’homme n’a pas de nature préalable : il se définit par ses actes"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m6"]},"explication":"Elle **joue** à être déléguée : comme le garçon de café du cours, elle joue son rôle."},{"cle":{"type":"choix","ids":["b"]},"explication":"Elle se réduit à une **chose**, la déléguée, pour **fuir sa liberté** : c’est la **mauvaise foi**."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c1","i4":"c0"}},"explication":"Les mensonges à soi-même relèvent de la **mauvaise foi** ; la **honte** sous le regard relève d’**autrui**."},{"cle":{"type":"choix","ids":["d"]},"explication":"Parce que « l’existence précède l’essence » : l’homme se définit **par ses actes**."}]$ex$::jsonb),
  ('7e717ad7-f0e2-5209-8295-7b35d5178626'::uuid, 1, 1, 5, 20, 3,
