  ('7e717ad7-f0e2-5209-8295-7b35d5178626'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Du rire taillé au rire des lords","competence":"analyser-texte","situation":"Lis un résumé du roman (écrit pour l’exercice), puis suis les grands moments de la vie de Gwynplaine.","documents":[{"id":"res","type":"texte","genre":"recit","titre":"Le roman en bref","blocs":["Angleterre, fin du XVIIe siècle. Enfant, Gwynplaine est vendu à des comprachicos qui taillent son visage en un rire perpétuel. Abandonné dans la neige, il sauve un bébé aveugle, Dea.","Le forain Ursus et son loup les recueillent, et le public vient rire de Gwynplaine. Un jour, un document prouve qu’il est lord Clancharlie. À la Chambre des lords, il parle de la misère du peuple, mais les lords éclatent de rire à cause de son visage.","Il renonce, retrouve la jeune aveugle mourante, et se jette à la mer."],"source":"Résumé écrit pour l’exercice"}],"questions":[{"enonce":"Touche le mot qui nomme ceux qui ont défiguré Gwynplaine.","aide":"Ils l’ont acheté enfant.","type":"zone","document":"res","multiple":false},{"enonce":"Pourquoi les lords rient-ils pendant son discours ?","aide":"Ils regardent son visage au lieu d’écouter ses mots.","type":"choix","options":[{"id":"a","texte":"Parce qu’ils l’ont pris pour un autre lord"},{"id":"b","texte":"À cause de son visage figé en rire"},{"id":"c","texte":"Parce qu’Ursus a lancé une farce depuis la salle"},{"id":"d","texte":"À cause d’une plaisanterie qu’il a préparée"}],"multiple":false},{"enonce":"Touche le prénom de l’enfant aveugle qu’il sauve dans la neige.","aide":"C’est le premier acte de bonté du récit.","type":"zone","document":"res","multiple":false},{"enonce":"Relie chaque personnage à son rôle dans l’intrigue.","aide":"Un intrigant, une duchesse, un forain et son animal.","type":"association","gauche":[{"id":"g0","texte":"Barkilphedro"},{"id":"g1","texte":"Josiane"},{"id":"g2","texte":"Ursus"},{"id":"g3","texte":"Homo"}],"droite":[{"id":"d0","texte":"La duchesse attirée par la monstruosité de Gwynplaine"},{"id":"d1","texte":"Le loup d’Ursus"},{"id":"d2","texte":"L’intrigant jaloux qui déclenche la révélation"},{"id":"d3","texte":"Le forain qui recueille les enfants"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m11"]},"explication":"Les **comprachicos** ont taillé son visage en un rire perpétuel."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les lords rient à cause de son **visage**, pas de son discours sur la misère du peuple."},{"cle":{"type":"zone","ids":["m29"]},"explication":"Il sauve **Dea**, qui l’aimera sans voir son visage."},{"cle":{"type":"association","paires":{"g1":"d0","g3":"d1","g0":"d2","g2":"d3"}},"explication":"**Barkilphedro** révèle ; **Josiane** est attirée ; **Ursus** recueille ; **Homo** est son loup."}]$ex$::jsonb),
  ('7e717ad7-f0e2-5209-8295-7b35d5178626'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Le rire que les lords n’ont pas compris","competence":"argumenter","situation":"Deux élèves se disputent sur la scène des lords. Lis les paroles de Gwynplaine, puis tranche.","documents":[{"id":"txt","type":"texte","genre":"recit","titre":"Les paroles de Gwynplaine","blocs":["« Mylords, je viens vous apprendre une nouvelle. Le genre humain existe. »","« Je suis celui qui vient des profondeurs. »"],"source":"Victor Hugo, *L’Homme qui rit* (1869) : paroles de Gwynplaine, citées par le cours"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Tom","emoji":"👧","cote":"gauche"},{"nom":"Nour","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nour","texte":"Les lords rient : Gwynplaine a donc échoué, son discours était ridicule."},{"qui":"Tom","texte":"Non : ce n’est pas son discours qu’ils trouvent comique, c’est son visage."},{"qui":"Nour","texte":"Alors pourquoi le roman insiste-t-il sur ce rire ?"},{"qui":"Tom","texte":"Parce que le rire figé symbolise le peuple, condamné à faire rire ceux qui le dominent."}]}],"questions":[{"enonce":"Touche les deux mots qui nomment ceux au nom de qui Gwynplaine parle.","aide":"Il ne parle pas seulement pour lui : il parle pour tous.","type":"zone","document":"txt","multiple":true},{"enonce":"Qui lit juste, d’après le débat et le cours ?","aide":"Relis la dernière réplique de Nour.","type":"choix","options":[{"id":"a","texte":"Tom : le rire montre que Gwynplaine est un faux lord"},{"id":"b","texte":"Nour : le rire vise son visage, et symbolise le peuple moqué"},{"id":"c","texte":"Nour : les lords rient parce qu’ils approuvent le discours"},{"id":"d","texte":"Tom : le discours échoue parce qu’il est mal construit"}],"multiple":false},{"enonce":"Relie chaque marque de Hugo à son exemple.","aide":"Une marque d’écriture, un exemple de roman.","type":"association","gauche":[{"id":"g0","texte":"Les contrastes"},{"id":"g1","texte":"Le style incantatoire"},{"id":"g2","texte":"Les digressions historiques"}],"droite":[{"id":"d0","texte":"Les grandes tirades"},{"id":"d1","texte":"Les pages sur l’Angleterre et ses lords"},{"id":"d2","texte":"Monstre et beauté, aveugle qui voit, rire et douleur"}]},{"enonce":"Quel thème le discours devant les lords illustre-t-il ?","aide":"Gwynplaine parle pour le peuple, mais personne ne l’écoute.","type":"choix","options":[{"id":"a","texte":"La justice sociale, portée par un discours inutile"},{"id":"b","texte":"Le triomphe de l’aristocratie sur la misère"},{"id":"c","texte":"La victoire facile du peuple sur ses maîtres"},{"id":"d","texte":"Le pardon accordé aux comprachicos"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m8","m9"]},"explication":"Il parle au nom du **genre humain**, c’est-à-dire du peuple que les lords ignorent."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le **rire figé** est une image : le peuple, quoi qu’il dise, **fait rire ceux qui le dominent**."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**Contrastes**, **tirades incantatoires** et **digressions** sont trois signatures de Hugo."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le discours porte la **justice sociale**, mais il est **inutile** : on rit de celui qui parle."}]$ex$::jsonb),
