  ('3fb6e509-aecb-583a-8719-37b15d556089'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Quatre naufragés, trois ans","competence":"analyser-texte","situation":"Lis un résumé de la pièce (écrit pour l’exercice), puis suis ce qui arrive aux quatre naufragés.","documents":[{"id":"res","type":"texte","genre":"recit","titre":"La pièce en bref","blocs":["Une tempête jette quatre naufragés sur une île peuplée d’anciens esclaves révoltés : le maître athénien Iphicrate, son esclave Arlequin, la dame Euphrosine et sa servante Cléanthis.","Le gouverneur Trivelin applique la loi de l’île : maîtres et serviteurs échangent noms, habits et conditions pour trois ans.","Arlequin et Cléanthis dressent alors des portraits impitoyables de leurs anciens maîtres. Pourtant, quand ils pourraient se venger, ils pardonnent. Les rôles sont rendus, et tous rentrent à Athènes, changés."],"source":"Résumé écrit pour l’exercice"}],"questions":[{"enonce":"Touche le nom du gouverneur qui applique la loi de l’île.","aide":"Son nom apparaît dans le second paragraphe.","type":"zone","document":"res","multiple":false},{"enonce":"Quel est le but de la loi de l’île ?","aide":"Trivelin parle de « se corriger ».","type":"choix","options":[{"id":"a","texte":"Corriger les maîtres, sans leur ôter la vie"},{"id":"b","texte":"Abolir pour toujours la différence entre les conditions"},{"id":"c","texte":"Venger les anciens esclaves en tuant leurs maîtres"},{"id":"d","texte":"Enrichir les serviteurs aux dépens de leurs maîtres"}],"multiple":false},{"enonce":"Touche le mot qui marque le retournement de l’intrigue.","aide":"Ils pourraient se venger, mais…","type":"zone","document":"res","multiple":false},{"enonce":"Relie chaque personnage à son rôle.","aide":"Une seule personne applique la loi ; les autres la subissent.","type":"association","gauche":[{"id":"g0","texte":"Trivelin"},{"id":"g1","texte":"Arlequin"},{"id":"g2","texte":"Cléanthis"},{"id":"g3","texte":"Euphrosine"}],"droite":[{"id":"d0","texte":"La dame qui doit se corriger"},{"id":"d1","texte":"La servante d’Euphrosine"},{"id":"d2","texte":"Le gouverneur qui applique la loi"},{"id":"d3","texte":"L’ancien esclave, devenu maître"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m29"]},"explication":"**Trivelin** est le gouverneur : il applique la loi de l’île."},{"cle":{"type":"choix","ids":["a"]},"explication":"La loi vise à **corriger** les maîtres : le but est moral, non sanglant."},{"cle":{"type":"zone","ids":["m66"]},"explication":"Arlequin et Cléanthis **pardonnent** : c’est le retournement et la source de l’émotion."},{"cle":{"type":"association","paires":{"g3":"d0","g2":"d1","g0":"d2","g1":"d3"}},"explication":"**Trivelin** applique ; **Arlequin** et **Cléanthis** changent de rang ; **Euphrosine** apprend."}]$ex$::jsonb),
