   $ex${"titre":"Corriger les cœurs, pas les abolir","competence":"argumenter","situation":"Deux élèves se disputent : la pièce est-elle révolutionnaire ? Lis la réplique de Trivelin, puis tranche.","documents":[{"id":"txt","type":"texte","genre":"theatre","titre":"Trivelin explique la loi","blocs":[{"personnage":"Trivelin","replique":"« Nous ne nous vengeons plus de vous, nous vous corrigeons ; ce n’est plus votre vie que nous poursuivons, c’est la barbarie de vos cœurs que nous voulons détruire. »"}],"source":"Marivaux, *L’Île des esclaves* (1725) : réplique citée par le cours"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Chloé","emoji":"👧","cote":"gauche"},{"nom":"Yanis","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Chloé","texte":"Cette pièce est révolutionnaire : elle veut abolir les maîtres."},{"qui":"Yanis","texte":"Pas du tout : Trivelin parle de corriger la barbarie des cœurs, pas de supprimer les conditions."},{"qui":"Chloé","texte":"Mais les maîtres sont humiliés !"},{"qui":"Yanis","texte":"Oui, pour apprendre ce qu’ils font subir : c’est une leçon, pas une vengeance."}]}],"questions":[{"enonce":"Touche les deux verbes qui opposent vengeance et correction.","aide":"Il y a un verbe nié et un verbe affirmé.","type":"zone","document":"txt","multiple":true},{"enonce":"Qui lit juste, d’après la réplique et le débat ?","aide":"Que veut détruire Trivelin ?","type":"choix","options":[{"id":"a","texte":"Chloé : la loi veut la mort des anciens maîtres"},{"id":"b","texte":"Yanis : la loi punit les esclaves trop doux"},{"id":"c","texte":"Yanis : la loi vise la dureté des maîtres, non leur existence"},{"id":"d","texte":"Chloé : la loi supprime définitivement les maîtres"}],"multiple":false},{"enonce":"Range chaque idée : la pièce est-elle cela, ou non ?","aide":"Marivaux veut rendre les conditions humaines, pas les abolir.","type":"categories","categories":[{"id":"c0","texte":"La pièce est"},{"id":"c1","texte":"La pièce n’est pas"}],"items":[{"id":"i0","texte":"Une abolition de toutes les conditions"},{"id":"i1","texte":"Une pièce révolutionnaire"},{"id":"i2","texte":"Une école morale pour les maîtres"},{"id":"i3","texte":"Une comédie fondée sur le décalage entre l’habit et la personne"},{"id":"i4","texte":"Une utopie pédagogique"}]},{"enonce":"Touche le mot qui nomme ce que la loi veut détruire.","aide":"Il s’agit du cœur des maîtres.","type":"zone","document":"txt","multiple":false}]}$ex$::jsonb,
